  "net-cylinder": "<svg preserveAspectRatio=\"xMidYMid meet\" xmlns=\"http://www.w3.org/2000/svg\" width=\"330\" height=\"238\" viewBox=\"0 0 330 238\" font-family=\"serif\"> <rect width=\"330\" height=\"238\" fill=\"none\"/> <rect x=\"105.0\" y=\"72.0\" width=\"150.0\" height=\"84.0\" fill=\"#fdf1f4\" stroke=\"#b03a55\" stroke-width=\"1.6\"/> <circle cx=\"180.0\" cy=\"48.1\" r=\"23.9\" fill=\"#fdf1f4\" stroke=\"#b03a55\" stroke-width=\"1.6\"/> <circle cx=\"180.0\" cy=\"179.9\" r=\"23.9\" fill=\"#fdf1f4\" stroke=\"#b03a55\" stroke-width=\"1.6\"/> <text x=\"180.0\" y=\"104.0\" font-size=\"11.5\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#8a2f44\" font-family=\"'Microsoft JhengHei','PingFang TC','Noto Sans TC',sans-serif\">側面（長方形）</text> <text x=\"180.0\" y=\"124.0\" font-size=\"11.5\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#8a2f44\">長 = 2πr</text> <text x=\"93.0\" y=\"114.0\" font-size=\"12\" text-anchor=\"end\" dominant-baseline=\"middle\" fill=\"#3a2126\" style=\"font-style:italic\">h</text> <line x1=\"99.0\" y1=\"72.0\" x2=\"99.0\" y2=\"156.0\" stroke=\"#c3aaae\" stroke-width=\"1.2\" stroke-linecap=\"round\"/> <text x=\"215.9\" y=\"48.1\" font-size=\"12\" text-anchor=\"start\" dominant-baseline=\"middle\" fill=\"#8a7378\" style=\"font-style:italic\">r</text> <line x1=\"180.0\" y1=\"48.1\" x2=\"203.9\" y2=\"48.1\" stroke=\"#c3aaae\" stroke-width=\"1.2\" stroke-linecap=\"round\"/> <text x=\"165.0\" y=\"223.7\" font-size=\"11.5\" text-anchor=\"middle\" dominant-baseline=\"middle\" fill=\"#6b5257\" font-family=\"'Microsoft JhengHei','PingFang TC','Noto Sans TC',sans-serif\" class=\"cap\">表面積 = 2πr² + 2πr·h</text> </svg>",
